import{_ as r,C as e,o as d,c as i,E as a,a2 as l}from"./chunks/framework.Cm6XCzck.js";const c="/joinwell52/assets/execution-artifacts-20260906/01-cancellation-inline-v1.png",A=JSON.parse('{"title":"点了取消，究竟取消了哪一步？一次 Agent 执行边界实验","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"点了取消，究竟取消了哪一步？一次 Agent 执行边界实验","date":"2026-09-06","published_date":"2026-09-07","column":"open-source-engineering","category":"daily","article_type":"engineering-case-study","edition":"research-center","summary":"发出取消请求、取消被接受、动作被阻止，是三个不同的事实。我们用真实审批服务和会话适配器做受控对照，发现有些看似越界的执行其实来自对接口语义的误读；真正还需要验证的，是授权答复交出之后、动作发生之前的等待窗口。","cover":"/assets/execution-artifacts-20260906/01-cancellation-cover-v2.png","language":"zh-CN","lifecycle":"Published","publication_authorized":true,"evidence_status":"Controlled study complete; no new product defect or development authorization","pageClass":"execution-artifacts-article"},"headers":[],"relativePath":"zh/engineering/2026-09-06-cancellation-execution-boundary.md","filePath":"zh/engineering/2026-09-06-cancellation-execution-boundary.md","lastUpdated":1788751356000}'),p={name:"zh/engineering/2026-09-06-cancellation-execution-boundary.md"};function s(h,t,u,g,_,b){const n=e("ArticleCover"),o=e("ArticleTableScroll");return d(),i("div",null,[a(n,{image:"/assets/execution-artifacts-20260906/01-cancellation-cover-v2.png",kicker:"开源工程观察 · 受控实验",title:"点了取消，究竟取消了哪一步？一次 Agent 执行边界实验",summary:"发出取消请求、取消被接受、动作被阻止，是三个不同的事实。我们用真实审批服务和会话适配器做受控对照，发现有些看似越界的执行其实来自对接口语义的误读；真正还需要验证的，是授权答复交出之后、动作发生之前的等待窗口。",version:"2026-09-06",languageHref:"/en/engineering/2026-09-06-cancellation-execution-boundary",languageLabel:"English"}),a(o,{language:"zh"}),t[0]||(t[0]=l('<p><a href="https://joinwell52-ai.github.io/joinwell52/assets/execution-artifacts-20260906/01-cancellation-cover-v2.png" target="_blank" rel="noreferrer">查看题图原图</a></p><h1 id="点了取消-究竟取消了哪一步-一次-agent-执行边界实验" tabindex="-1">点了取消，究竟取消了哪一步？一次 Agent 执行边界实验 <a class="header-anchor" href="#点了取消-究竟取消了哪一步-一次-agent-执行边界实验" aria-label="Permalink to &quot;点了取消，究竟取消了哪一步？一次 Agent 执行边界实验&quot;">​</a></h1><p>让 AI 助手修改文件，最让人不安的时刻之一，是你已经改变主意，它却还显示“正在处理”。</p><p>你点了取消。接下来，它应当不再开始新动作，还是立即终止正在执行的命令？如果文件已经写了一半，是停下来、写完再停，还是恢复原状？</p><p>这些不是同一个承诺。一个“取消”按钮可以表达明确的用户意愿，却不能单凭点击本身证明执行端已经接受请求，更不能证明外部动作尚未发生。</p><p>我们最近做的一组实验，恰好遇到了这种容易下错结论的现场：执行器在等待，我们发出取消，随后文件仍然写入成功。只看前后顺序，很容易写成“取消后仍执行”。但检查回执后，结论必须改变——<strong>那次取消请求根本没有被接受。</strong></p><p>这篇文章要讲的，不是一个已经修好的取消漏洞，而是如何把“我要求它停”追踪到“哪一步确实停了”。</p><p>为此，我们分别检查<strong>取消待审批请求、结束会话、动作执行前中止</strong>三个边界。它们不是同一个接口，也不承诺相同结果：下文先看审批服务，再看会话适配器，动作前的额外中止检查则只作为研究对照，不是一次界面按钮的端到端测试。</p><h2 id="_1-一个值得追问的窗口-检查之后-还要等多久" tabindex="-1">1. 一个值得追问的窗口：检查之后，还要等多久？ <a class="header-anchor" href="#_1-一个值得追问的窗口-检查之后-还要等多久" aria-label="Permalink to &quot;1. 一个值得追问的窗口：检查之后，还要等多久？&quot;">​</a></h2><p>OpenHands 是面向软件开发任务的开源 Agent 项目，其 SDK 提供工具执行等基础能力。这里的 Agent，指能够调用工具采取动作的 AI 助手，而不只是回答问题的聊天模型。</p><p>OpenHands SDK 的 <a href="https://github.com/OpenHands/software-agent-sdk/pull/4866" target="_blank" rel="noreferrer">#4866 提案</a>讨论了一段具体顺序：工具执行前检查取消标记，随后等待资源锁；如果等待期间发生取消，拿到锁之后是否还会调用工具？提案试图在获得锁后再检查一次。核验截至 2026 年 9 月 6 日，该 PR 已关闭、未合并，作者说明将重新提交并修正证据。它是研究线索，不是本文独立复现的上游事故，也不能写成已经交付的修复。</p><p>它照亮的问题很有价值：<strong>检查与动作之间如果隔着等待，先前判断是否仍然有效？</strong></p><p>例如，工具要使用一个被其他任务占用的环境。进入队列时可以运行，不等于轮到它时仍应运行。但要判断系统是否真的有问题，必须先回答：取消入口承诺撤销什么？请求有没有成功？等待发生在哪一层？</p><p>因此，我们没有直接给自己的系统加一个“再检查一次”的功能，而是先测已有边界。</p><h2 id="_2-第一个反例-过了期限执行-不一定是授权过期后执行" tabindex="-1">2. 第一个反例：过了期限执行，不一定是授权过期后执行 <a class="header-anchor" href="#_2-第一个反例-过了期限执行-不一定是授权过期后执行" aria-label="Permalink to &quot;2. 第一个反例：过了期限执行，不一定是授权过期后执行&quot;">​</a></h2><p>CodeFlowMu 是我们在开发的本地多 Agent 协作系统，围绕任务文件、执行会话和证据组织工作。本轮使用固定源码基线 <code>c008d9db91a21136fc61a4f60314e22db395d5d2</code>，在独立合成目录里调用真实审批服务；没有取消用户的在线任务，也没有修改产品代码。</p><p>先测正常路径：批准一个精确的文件操作，执行一次，再尝试重复执行。两轮都是首次成功、文件效果一次；第二次被拒绝，返回 <code>APPROVAL_ALREADY_CONSUMED</code>，即这份批准已经被消费。</p><p>然后测试时间。我们通过服务提供的时钟注入接口，把待审批期限设为 30 秒，不靠随机等待制造竞态。</p><table tabindex="0"><thead><tr><th>场景</th><th>实际结果，两轮一致</th><th>能得出的判断</th></tr></thead><tbody><tr><td>尚未批准，先取消，再尝试执行</td><td>请求进入取消状态；未签发凭据的执行尝试被拒绝；文件效果 0 次</td><td>验证了取消状态与未获批执行的拒绝，未验证已批准令牌的撤销</td></tr><tr><td>一直未批准，超过 30 秒</td><td>状态变为过期；批准被拒绝；文件效果 0 次</td><td>待审批期限有效</td></tr><tr><td>期限内批准，第 31 秒执行</td><td>执行成功；文件效果 1 次</td><td>需要核对期限约束的对象，不能直接报漏洞</td></tr></tbody></table><p>第三行看上去最可疑：记录里的 <code>expires_at</code> 是第 30 秒，为什么第 31 秒还可以执行？</p><p>第一行也有一个需要保留的前提：请求还没有获批，因此执行尝试使用的不是已签发令牌。这一组验证待审批取消和未获批执行的拒绝，不能拿来证明“已经批准的令牌可以撤销”。</p><p>源码给出了明确答案：这一期限约束的是<strong>等待审批的时间</strong>。既有测试还明确要求，已经批准的令牌可以在待审批截止时间之后使用。令牌在这里是执行时出示的批准凭据，不是对所有操作都承诺相同失效规则的通行证。</p><p>于是，本次观察不能命名为“绕过授权有效期”。准确的说法是：待审批截止时间，不是批准后的通用执行截止时间。</p><p>如果产品将来需要“批准十分钟后也不得执行”，那是另一条应当明确制定并验收的规则。不能先给现有字段赋予它没有承诺的含义，再把结果当成安全缺陷。</p><h2 id="_3-第二个反例-执行器在等-取消为什么被拒绝" tabindex="-1">3. 第二个反例：执行器在等，取消为什么被拒绝？ <a class="header-anchor" href="#_3-第二个反例-执行器在等-取消为什么被拒绝" aria-label="Permalink to &quot;3. 第二个反例：执行器在等，取消为什么被拒绝？&quot;">​</a></h2><p>更关键的实验，是在审批服务已经进入执行器回调后，放置一个由脚本控制的等待点。回调可以理解为审批服务交给具体执行代码的入口。我们先暂停回调，发出取消请求，最后放行。</p><p>这里必须说清实验条件：等待是研究脚本注入的。受测本地文件执行器使用同步文件操作，本轮没有复现 OpenHands 式的真实资源锁队列。</p><table tabindex="0"><thead><tr><th>场景</th><th>取消回执</th><th>最终文件效果</th><th>解释</th></tr></thead><tbody><tr><td>回调进入后等待，取消，再放行</td><td><code>APPROVAL_NOT_PENDING</code>，取消被拒绝</td><td>1 次</td><td>不是“成功取消后仍执行”</td></tr><tr><td>相同等待，但研究回调在放行后检查自设中止标记</td><td>取消仍被拒绝</td><td>0 次，回调抛错</td><td>说明动作前检查可以改变结果，不是产品新增能力</td></tr><tr><td>文件效果已经发生，等待收尾时再取消</td><td>取消被拒绝</td><td>已发生的 1 次效果仍在</td><td>不能把事后请求当成自动回滚</td></tr></tbody></table><p>三组场景各在新建的独立实验目录中运行两轮，结果一致。</p><p><img src="'+c+'" alt="取消回执与实际文件效果的三组受控实验对照"></p><p><em>图 1：对应 A1、A4、A5：第三行的额外中止检查仅由研究回调提供。等待不是产品真实资源队列；待审批场景没有已签发令牌。 来源：本文受控实验，AI 绘制的解释图。</em></p><p><a href="https://joinwell52-ai.github.io/joinwell52/assets/execution-artifacts-20260906/01-cancellation-inline-v1.png" target="_blank" rel="noreferrer">查看文中图原图</a></p><p>为什么第一组取消失败？审批服务在校验批准状态、令牌和请求摘要后，先把记录推进为 <code>executing</code>，表示进入执行器阶段，再调用回调。而其取消接口只接受尚待处理的审批。</p><p>所以，等待时的 <code>executing</code> 不证明文件已经写入；<code>APPROVAL_NOT_PENDING</code> 则确实证明这次审批取消没有成功。两条事实必须分别保留。</p><p>第二组是有意设置的机制对照：研究回调在等待结束后看到中止标记，于是没有调用真实文件执行器。它说明改变检查位置可以改变结果；这里起作用的是研究脚本的中止标记，不是被拒绝的审批取消请求。</p><p>这也是本轮研究的分水岭。<strong>“发出了取消请求”不能替代“取消已经被接受”；“进入执行器”也不能替代“效果已经发生”。</strong></p><h2 id="_4-已有保护不能因为新选题而被忽略" tabindex="-1">4. 已有保护不能因为新选题而被忽略 <a class="header-anchor" href="#_4-已有保护不能因为新选题而被忽略" aria-label="Permalink to &quot;4. 已有保护不能因为新选题而被忽略&quot;">​</a></h2><p>审批服务不是整个执行链。CodeFlowMu 还有连接编程 Agent 的会话适配器，负责接收请求、处理审批答复以及结束会话。</p><p>我们进一步测试了自己的 Codex 会话适配器：使用真实 <code>CodexAppServerRunHandle</code> 类，接入内存中的伪进程通信流，不启动真实 Codex，也不执行终端工具。</p><p>观察点只有一个：最终是否发送批准答复。</p><table tabindex="0"><thead><tr><th>场景</th><th>每轮实际发送的批准答复</th></tr></thead><tbody><tr><td>正常请求，答复前未取消</td><td>1 次</td></tr><tr><td>请求已经收到，异步处理尚未返回时取消会话</td><td>0 次</td></tr><tr><td>会话取消后，迟到请求才到达</td><td>0 次</td></tr></tbody></table><p>这三个场景各跑两轮。结果说明，在受测适配器边界，会话结束后存在阻止迟到答复的保护。这里不应再宣称“系统完全没有最后一道检查”。</p><p>但答复没有发出，与真实宿主内部的工具没有执行，仍然是不同命题。宿主指实际承载 Agent 和工具的执行程序。如果答复已经交给它，随后工具又等待资源，那个等待窗口里的规则还需要在具体宿主中验证。</p><p>本地适配器做对一件事，不能替另一个进程提供保证；同样，外部项目发现一个窗口，也不能抹掉本地已经验证的保护。</p><h2 id="_5-取消应该留下怎样的证据" tabindex="-1">5. 取消应该留下怎样的证据？ <a class="header-anchor" href="#_5-取消应该留下怎样的证据" aria-label="Permalink to &quot;5. 取消应该留下怎样的证据？&quot;">​</a></h2><p>如果要继续研究真正的工具队列，最有区分力的记录不是最后一个 <code>cancelled</code> 状态，而是一条能够对齐的时间线：</p><blockquote><p>取消请求到达 → 接受或拒绝的回执 → 等待结束 → 最后一次有效性检查 → 真实动作开始 → 效果与收尾。</p></blockquote><p>这是一份后续实验建议，不是本轮已经实现的统一接口。</p><p>每一步回答不同的问题：接受回执说明系统承诺了什么；动作开始点说明承诺是否来得及生效；效果记录说明是否还有需要对账或补救的事情。已经发生的外部动作，需要另行定义补偿，不能仅靠停止后续计算把它变成“没发生”。</p><p>对工程团队，最值得先检查的也不是“哪里再插一个取消标记”，而是下面三件事：</p><ul><li>界面有没有把“正在请求取消”提前显示成“已经停止”？</li><li>每个取消入口到底针对待审批、整个会话，还是某个正在运行的动作？</li><li>对资源等待，能否证明检查发生在等待之后、动作之前，而不只是函数入口？</li></ul><p>本轮把已有保护与待测窗口分开了：审批取消只处理待审批请求，会话适配器能够阻止受测场景中的迟到答复，而答复已经交出后的真实工具队列仍需另测。下一步应沿这条边界找证据，再决定是否开发。</p><p><strong>可靠的取消，不是让所有地方都写着“已取消”，而是能说明：请求在哪一层被接受，阻止了哪一步，还有什么事实没有被改变。</strong></p><h2 id="证据与范围" tabindex="-1">证据与范围 <a class="header-anchor" href="#证据与范围" aria-label="Permalink to &quot;证据与范围&quot;">​</a></h2><p>本篇使用 7 个审批场景和 3 个适配器场景，各两轮；不是生产事故统计，也不是安全准确率。研究还对由两个既有测试文件组成的基线测试集运行两轮，每轮合计 39 项通过、0 失败、0 跳过，不能把它们相加成端到端保证。</p><p>第一方原始记录为 <code>boundaries-1788695589568.json</code> 的 A0–A6 和 <code>adapter-1788695732064.json</code>；适配器正常场景最后的取消状态来自测试清理，不是正常执行失败。<a href="/joinwell52/zh/research/evidence/2026-09-06-execution-artifact-continuity">双语证据包</a>提供全部脱敏观测、来源、两轮基线日志、研究探针和完整性校验。公开包去除本机路径和进程编号，保留结果与顺序；运行产品探针仍需有权访问固定源码及其依赖，不能把记录校验当成产品复跑。本文写作进行了记录复核，没有新增真实宿主测试。</p><p>真实资源队列、操作系统进程退出、外部效果撤销以及授权变更后的实际工具行为，均不在本轮已验证范围内。</p>',57))])}const m=r(p,[["render",s]]);export{A as __pageData,m as default};
